const selections=JSON.parse(readFileSync(join(run,'control/semantic-producer-context',call+'.json'),'utf8'));
const view=semanticProducerView(model,'extractor','S2',selections);
const bad=validateSemanticReturn('extractor','1.9.0-provisional',raw,view.context);
assert.equal(bad.result,'FAIL');assert.match(bad.errors.join(';'),/material outside assigned source scope/);
