const text=inventory.objects.find(o=>o.representation_id===rep.representation_id&&o.kind==='text')!;
const corrected=structuredClone(raw);
corrected.packets[0].material_use.requirements=[{object_id:text.object_id,feature:'text-bytes',binding_ids:JSON.parse(text.binding_ids)}];
const good=validateSemanticReturn('extractor','1.9.0-provisional',corrected,view.context);
assert.equal(good.result,'PASS',good.errors.join(';'));assert.equal(good.binding,'checked');
console.log(JSON.stringify({case:'second-source material scope',original:bad,corrected:good.result,source:raw.source_id,requirement:corrected.packets[0].material_use.requirements}));
