 const output={kind:'indeterminate-claim' as const, output_selector:'claim-candidate:0',output_index:0,reserved_claim_id:'CC-0702',normalized_claim:'Tentative unadmitted interpretation.',packet_ids:['PKT-0701'],source_ids:['SRC-701'],claim_type:'factual'};
