 const derive=()=>semanticIndeterminateClaimMaterialViews(m,output,materialHash('fixture'),use);
 if(lf) assert.throws(derive,/SRC binding outside exact packet-basis union/);
 else assert.equal(derive().length,1);
 console.log(JSON.stringify({case:'C04 multi-object packet union',source_trailing_LF:lf,result:lf?'expected Core refusal':'PASS exact preview',run:f.run}));
}

